# Generated by `shiny theme new` from shiny-snowfall.png
# Base scheme: Iceberg Dark — https://github.com/mbadolato/iTerm2-Color-Schemes (via Ghostty)
# Edit freely; `shiny theme set <name>` re-applies.
THEME_BASE="Iceberg Dark"
GHOSTTY_THEME="Iceberg Dark"   # built-in: ghostty +list-themes
ACCENT_PRESET=4                    # macOS accent: -1 graphite 0 red 1 orange 2 yellow 3 green 4 blue 5 purple 6 pink
WALLPAPER="wallpaper.jpg"

BG="#161821"         # window background
BG_DARK="#12141B"    # frames, omnibox
SURFACE="#282A33"    # borders, dividers, inactive window border
SELECTION="#313948"  # selected rows, text selection
MUTED="#474952"      # shortcuts, scrollbar
COMMENT="#60626B"    # subtext, inactive tabs
FG="#C6C8D1"         # primary text
FG_DIM="#A6A8B1"     # secondary text
ACCENT="#91ACD1"     # primary accent: focus border, icons, links, text highlight, icon tint
ACCENT2="#95C4CE"    # secondary accent: cursor, shortcuts, search selection
